     7	
     8	const createDownloadLink = (href: string, fileName: string) => {
     9	    // creating anchor tag to initiate download
    10	    const link = document.createElement('a');
    11	    // adding href to anchor
    12	    link.href = href;
    13	    link.style.display = 'none';
    14	
    15	    // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Disabling this line for safeness as nullish coalescing works only if the value is undefined or null, and since fileName can be an empty string we want to default to `FileUtils.getFileName(url)`
    16	    link.download = fileName;
    17	
    18	    // Append to html link element page
    19	    document.body.appendChild(link);
    20	
    21	    // Start download
    22	    link.click();
    23	
    24	    // Clean up and remove the link
    25	    URL.revokeObjectURL(link.href);
    26	    link.parentNode?.removeChild(link);
    27	};
