    29	/**
    30	 * The function downloads an attachment on web/desktop platforms.
    31	 */
    32	// eslint-disable-next-line @typescript-eslint/no-unused-vars
    33	const fetchFileDownload: FileDownload = (url, fileName, successMessage = '', shouldOpenExternalLink = false, formData = undefined, requestType = 'get', onDownloadFailed?: () => void) => {
    34	    const resolvedUrl = tryResolveUrlFromApiRoot(url);
    35	
    36	    const isApiUrl = resolvedUrl.startsWith(ApiUtils.getApiRoot());
    37	    const isAttachmentUrl = CONST.ATTACHMENT_LOCAL_URL_PREFIX.some((prefix) => resolvedUrl.startsWith(prefix));
    38	    const isSageUrl = url === CONST.EXPENSIFY_PACKAGE_FOR_SAGE_INTACCT;
    39	    if (
    40	        // We have two file download cases that we should allow: 1. downloading attachments 2. downloading Expensify package for Sage Intacct
    41	        shouldOpenExternalLink ||
    42	        (!isApiUrl && !isAttachmentUrl && !isSageUrl)
    43	    ) {
    44	        // Different origin URLs might pose a CORS issue during direct downloads.
    45	        // Opening in a new tab avoids this limitation, letting the browser handle the download.
    46	        Link.openExternalLink(url);
    47	        return Promise.resolve();
    48	    }
    49	
    50	    const fetchOptions: RequestInit = {
    51	        method: requestType,
    52	        body: formData,
    53	    };
    54	
    55	    return fetch(url, fetchOptions)
    56	        .then((response) => {
    57	            const contentType = response.headers.get('content-type');
    58	            if (contentType === 'application/json' && fileName?.includes('.csv')) {
    59	                throw new Error();
    60	            }
    61	            return response.blob();
    62	        })
    63	        .then((blob) => {
    64	            // Create blob link to download
    65	            const href = URL.createObjectURL(new Blob([blob]));
    66	            const completeFileName = FileUtils.appendTimeToFileName(fileName ?? FileUtils.getFileName(url));
    67	            createDownloadLink(href, completeFileName);
    68	        })
    69	        .catch(() => {
    70	            if (onDownloadFailed) {
    71	                onDownloadFailed();
    72	            } else {
    73	                // file could not be downloaded, open sourceURL in new tab
    74	                Link.openExternalLink(url);
    75	            }
    76	        });
    77	};
    78	
    79	export default fetchFileDownload;
