     9	type UseNetwork = {isOffline: boolean};
    10	
    11	export default function useNetwork({onReconnect = () => {}}: UseNetworkProps = {}): UseNetwork {
    12	    const callback = useRef(onReconnect);
    13	    callback.current = onReconnect;
    14	
    15	    const {isOffline, networkStatus} = useContext(NetworkContext) ?? {...CONST.DEFAULT_NETWORK_DATA, networkStatus: CONST.NETWORK.NETWORK_STATUS.UNKNOWN};
    16	    const prevOfflineStatusRef = useRef(isOffline);
    17	    useEffect(() => {
    18	        // If we were offline before and now we are not offline then we just reconnected
    19	        const didReconnect = prevOfflineStatusRef.current && !isOffline;
    20	        if (!didReconnect) {
    21	            return;
    22	        }
    23	
    24	        callback.current();
    25	    }, [isOffline]);
    26	
    27	    useEffect(() => {
    28	        // Used to store previous prop values to compare on next render
    29	        prevOfflineStatusRef.current = isOffline;
    30	    }, [isOffline]);
    31	
    32	    // If the network status is undefined, we don't treat it as offline. Otherwise, we utilize the isOffline prop.
    33	    return {isOffline: networkStatus === CONST.NETWORK.NETWORK_STATUS.UNKNOWN ? false : isOffline};
    34	}
